FROM ensino.turma t
JOIN ensino.docente_turma dt ON dt.id_turma = t.id_turma 
WHERE t.id_turma_serie IN (51895877, 51896191, 51896192, 51896072, 51896087,
51896075, 51896487, 51895876, 51895878, 51895804, 51896082, 51896488, 51896489,
51896490, 51896491, 51896492, 51896507, 51896524, 51896595, 51896637, 51896648);


